/* 
	Loading animation
	glowing circles of different sizes and colors moving to the right
	https://openprocessing.org/sketch/2137875
	#genuary7 #genuary #creativecoding #generativeart

	https://genuary.art/prompts#jan7
*/

let objs;
let SZE, NUMX, NUMY, CLRS;

function setup() {
	SZE = ~~random(25, 75);
	NUMX = ~~(windowWidth/SZE);
	NUMY = ~~(windowHeight/SZE);
	// createCanvas(SZE * NUMX, SZE * NUMY);
	createCanvas(windowWidth, windowHeight);
	describe("glowing circles of different sizes and colors moving to the right")
	pixelDensity(1)
	colorMode(HSB, 100);
	frameRate(60);
	CLRS = genColors(random(3, 6));
	initObjs();
}

function initObjs() {
	objs = [];
	for (let y = -1; y <= NUMY; y++) {
		if (abs(NUMY * 0.5 - y) > 1.65) continue;
		for (let x = -2; x <= NUMX+1; x++) {
			// positions
			const src = createVector(x * SZE + SZE * 0.5, y * SZE + SZE * 0.5)
			let DX = 0, DY = 0;
			let D = SZE * (random() < 0.5 ? -0.5 : 1);
			if (true || random() < 0.5) {
				DX = D;
			} else {
				DY = D;
			}
			// DX = 1; DY = 0;

			const dst = createVector(x * SZE + DX + SZE * 0.5, y * SZE + DY + SZE * 0.5)
			// move positions left of screen
			src.x -= width;
			dst.x -= width;
			// random color, with low chance of white
			const clr = random() < 0.9 ? random(CLRS) : color(0, 0, 100); // CLRS[0]
			// calculate size 
			const sze = random(SZE * 0.75, SZE * 1.25) * 
						(cos(abs(NUMX*0.5 - x)/(NUMX)*PI) + 0.2)
						// ((NUMX - x) / NUMX + 0.25);
			objs.push(new MovCircle(src, sze, dst, clr))
		}		
	}
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function draw() {
	// if (frameCount === 10) // noLoop() removed for animation
	blendMode(BLEND)
	// background("rgb(2, 0, 8)");
	const bgCol = color(65, 90, 4 + 6 * cos(frameCount * 0.025 + PI))
	const fgCol = color(65, 90, 33 + 12 * cos(frameCount * 0.025 + PI))
	background(bgCol)

	const ctx = drawingContext;
	const gradient = ctx.createLinearGradient(0, 0, width, 0);

	// Add three color stops
	gradient.addColorStop(0, bgCol);
	const befOrAfter = (~~(frameCount/60) % 2 === 0)
	const f = constrain(easeOutElastic(frameCount%60/60), 0, 1);
	if (true || befOrAfter && false) gradient.addColorStop(constrain(f-0.25, 0, 1), bgCol);
	gradient.addColorStop(f, fgCol);
	if (true || !befOrAfter && false) gradient.addColorStop(constrain(f+0.25, 0, 1), bgCol);
	gradient.addColorStop(1, bgCol);

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	// drawingContext.shadowBlur = 0
	// noStroke()
	// fill(bgCol)
	ctx.fillRect(0, 0, width, height);

	blendMode(ADD)

	for (let o of objs) {
		for (let i = 0; i < 10; i++) o.update(SZE);
		o.show();
	}

	// outer frame
	if (true) {
		bgImg = get(width * 0.05, height * 0.35, width * 0.9, height * 0.3)
		blendMode(BLEND);
		noStroke()
		fill("black")
		drawingContext.shadowBlur = 0;
		rect(0, 0, width, height)
		noFill()
		stroke("white")
		stroke(70, 0, 90 + 20 * cos(frameCount * 0.05 + PI))
		strokeWeight(2);
		drawingContext.shadowBlur = 25;
		drawingContext.shadowColor = color("white")
		rect(width * 0.05, height * 0.35, width * 0.9, height * 0.3, 3);
		image(bgImg, width * 0.05, height * 0.35)
		noFill();
		drawingContext.shadowBlur = 0;
		rect(width * 0.05, height * 0.35, width * 0.9, height * 0.3, 3);
	}
}

// easing.net
function easeOutElastic(x) {
const c4 = (2 * Math.PI) / 3;

return x === 0
  ? 0
  : x === 1
  ? 1
  : Math.pow(2, -10 * x) * Math.sin((x * 10 - 0.75) * c4) + 1;

}
function easeOutBounce(x) {
const n1 = 7.5625;
const d1 = 2.75;

if (x < 1 / d1) {
    return n1 * x * x;
} else if (x < 2 / d1) {
    return n1 * (x -= 1.5 / d1) * x + 0.75;
} else if (x < 2.5 / d1) {
    return n1 * (x -= 2.25 / d1) * x + 0.9375;
} else {
    return n1 * (x -= 2.625 / d1) * x + 0.984375;
}

}
function easeInBounce(x){
	return 1 - easeOutBounce(1 - x);
}
function easeInOutBounce(x) {
return x < 0.5
  ? (1 - easeOutBounce(1 - 2 * x)) / 2
  : (1 + easeOutBounce(2 * x - 1)) / 2;
}

function genColors(n = 2) {
	arr = [];
	const HUE = ~~random(100)
	const DLT = 100 / n;
	for (let i = 0; i < n; i++) {
		var clr = color((HUE + i * DLT) % 100, random(75, 100), random(50, 75));
		arr.push(clr)
	}
	return arr;
}

// class MovCircle
class MovCircle {
	constructor(src, sze, dst, clr) {
		this.pos = src.copy();
		this.src = src;
		this.sze = sze;
		this.dst = dst;
		this.clr = clr;
		this.easing = random([easeOutElastic, easeOutBounce, easeInBounce, easeInOutBounce]);
		this.animDuration = 20; // random(45, 75);
		this.animStart = frameCount;
		this.animEnd = frameCount + this.animDuration;
	}

	update(SZE) {
		if (frameCount >= this.animEnd) {
			// console.log("bef " + this.src.x + ", " + this.src.y + ", " + this.dst.x + ", " + this.dst.y)
			this.animStart = frameCount;
			this.animEnd = frameCount + this.animDuration;
			[this.src, this.dst] = [this.dst, this.src];
			// move partially to the right
			this.dst.x += SZE * 2;
			// console.log("aft " + this.src.x + ", " + this.src.y + ", " + this.dst.x + ", " + this.dst.y)
			// replace outer screen to left again
			if (this.src.x > width * 1.2) {
				this.src.x -= width * 1.2;
				this.dst.x -= width * 1.2;
			}
		}
		const amount = this.easing((frameCount - this.animStart) / (this.animEnd - this.animStart));
		this.pos = p5.Vector.lerp(this.src, this.dst, amount);
	}

	clrDeviation(clr) {
		const clrHue = hue(window.color(clr));
		const clrSat = saturation(window.color(clr));
		const clrBrg = brightness(window.color(clr));
		const clrAlp = alpha(window.color(clr));
		return color(clrHue + noise((this.pos.x + frameCount) * 0.00812, this.pos.y * 0.00932) * 60 - 30, clrSat, clrBrg);
	}

	show() {
		const cx = this.pos.x;
		const cy = this.pos.y;
		var clr = this.clrDeviation(this.clr);
		var sze = this.sze;

		noStroke()
		fill(clr)


		drawingContext.shadowBlur = sze * 0.4;
		drawingContext.shadowColor = "white";
		// circle(cx, cy, sze)

		drawingContext.shadowBlur = sze * 0.5;
		drawingContext.shadowColor = clr;
		circle(cx, cy, sze)

		/*
		drawingContext.shadowBlur = 0;
		fill(lerpColor(clr, color(255), 0.25))
		*/
		circle(cx, cy, sze)
	}
}
